<?php
require_once __DIR__ . '/../config/db.php';
$pageTitle='Edit Project | Freelance Marketplace System'; $id=intval($_GET['id']??0); $successMessage=''; $errorMessage=''; if($id<=0){header('Location: projects.php?error=Invalid project ID.'); exit;} $stmt=$conn->prepare("SELECT * FROM Project WHERE project_id = ?"); $stmt->bind_param('i',$id); $stmt->execute(); $project=$stmt->get_result()->fetch_assoc(); $stmt->close(); if(!$project){header('Location: projects.php?error=Project not found.'); exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??''); $description=trim($_POST['description']??''); $budget=trim($_POST['budget']??''); $datePosted=trim($_POST['date_posted']??''); $status=trim($_POST['status']??''); $clientId=trim($_POST['client_id']??''); if($title===''||$budget===''||$datePosted===''||$status===''||$clientId===''){$errorMessage='Please fill in all required fields.';} else {$stmt=$conn->prepare("UPDATE Project SET title = ?, description = ?, budget = ?, date_posted = ?, status = ?, client_id = ? WHERE project_id = ?"); $stmt->bind_param('ssdssii',$title,$description,$budget,$datePosted,$status,$clientId,$id); if($stmt->execute()){$successMessage='Project updated successfully.'; $project=array_merge($project,['title'=>$title,'description'=>$description,'budget'=>$budget,'date_posted'=>$datePosted,'status'=>$status,'client_id'=>$clientId]);}else{$errorMessage='Unable to update project.';} $stmt->close();}}
$clients=$conn->query("SELECT c.client_id, u.name FROM Client c INNER JOIN `User` u ON c.client_id = u.user_id ORDER BY u.name"); include __DIR__ . '/../includes/header.php'; include __DIR__ . '/../includes/navbar.php';
?>
<section class="form-card"><span class="eyebrow">Edit Record</span><h2 class="page-title">Edit Project #<?php echo $id; ?></h2><p class="page-intro">Update project information.</p><?php if($successMessage!==''):?><div class="message success"><?php echo htmlspecialchars($successMessage); ?></div><?php endif;?><?php if($errorMessage!==''):?><div class="message error"><?php echo htmlspecialchars($errorMessage); ?></div><?php endif;?><form method="POST" action=""><div class="form-row"><div><label for="title">Project Title *</label><input type="text" id="title" name="title" required value="<?php echo htmlspecialchars($project['title']); ?>"></div><div><label for="budget">Budget *</label><input type="number" step="0.01" id="budget" name="budget" required value="<?php echo htmlspecialchars($project['budget']); ?>"></div></div><div class="form-row"><div><label for="date_posted">Date Posted *</label><input type="date" id="date_posted" name="date_posted" required value="<?php echo htmlspecialchars($project['date_posted']); ?>"></div><div><label for="status">Status *</label><select id="status" name="status" required><option value="Open" <?php echo $project['status']==='Open'?'selected':''; ?>>Open</option><option value="In Progress" <?php echo $project['status']==='In Progress'?'selected':''; ?>>In Progress</option><option value="Completed" <?php echo $project['status']==='Completed'?'selected':''; ?>>Completed</option></select></div></div><div><label for="client_id">Client *</label><select id="client_id" name="client_id" required><?php while($client=$clients->fetch_assoc()):?><option value="<?php echo $client['client_id']; ?>" <?php echo ($client['client_id']==$project['client_id'])?'selected':''; ?>><?php echo htmlspecialchars($client['name']); ?> (ID: <?php echo $client['client_id']; ?>)</option><?php endwhile;?></select></div><div><label for="description">Description</label><textarea id="description" name="description"><?php echo htmlspecialchars($project['description'] ?? ''); ?></textarea></div><div class="form-actions"><button type="submit">Update Project</button><a class="btn btn-secondary" href="<?php echo $basePath; ?>/pages/projects.php">Cancel</a></div></form></section><?php include __DIR__ . '/../includes/footer.php'; $conn->close(); ?>
